script:
dsh.onData((data) => {
  const d = data.agent && data.agent.value
  if (!d) return
  document.querySelector('.tag').textContent = d.release.tag
  document.querySelector('.stars').textContent = '★ ' + dsh.fmt.number(d.stars)
  const a = document.querySelector('.name')
  a.textContent = d.release.name + ' · ' + dsh.fmt.ago(d.release.date)
  a.href = d.release.url
  document.querySelector('.hl').innerHTML = (d.release.highlights || []).map((h) => '<li>' + dsh.escape(h) + '</li>').join('')
})
